from taf.internal.aliasing import aliasing_scope
from robot.libraries.BuiltIn import BuiltIn
from taf.trafficgenerator.iperf.facade import IperfFacade, StopPrior
from taf.trafficgenerator.iperf.traffic_generator import IperfTrafficGenerator


class iperf(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    lookup_handler, store = aliasing_scope(lookup_arg='iperf', lookup_type=IperfTrafficGenerator)

    def __init__(self):
        self._iperf_facade = IperfFacade()

    @staticmethod
    def _create_log_path(log_path):
        if log_path is None or '/' in log_path or '\\' in log_path:
            return log_path
        else:
            logs_dir = BuiltIn().replace_variables('${OUTPUTDIR}')
            return logs_dir + '/' + log_path

    def create_iperf_server(self,
                            cmd_options=None,
                            iperf_path=None,
                            adb=False,
                            serial_number=None,
                            host_configuration=None,
                            log_path=None,
                            iperf_alias=None):
        """
        Create iperf server instance.

        :param cmd_options: (optional) iperf software options string or dictionary except for optional -s/server
        which is built-in from this Keyword
        if the ue pc has multiple network interfaces, please use -B/bind to specify one
        dict:
                udp, interval, port, bandwidth, len, interval, bind, time, format, ipv6_domain, window, realtime,
                print_mss, mss nodelay, tos, udp-counters-64bit
                supported iperf software options can be found from the following NAA iperf software help doc.
                https://artifactory-espoo1.ext.net.nokia.com/artifactory/mn-android-apk/iperf/
                e.g. Create Dictionary
            ...  udp=True
            ...  interval=1
            ...  port=54000
            ...  bandwidth=5000k
            ...  time=120
            ...  len=1000
            ...  bind=xxx.xxx.xxx.xxx
        string:
            e.g. -u -i 1 -p 12345 -t 100
        :type cmd_options: Union(str, dict)
        :param iperf_path: (optional) iperf path on the host, 'iperf' from $PATH by default
        :type iperf_path: str
        :param adb: (optional) flag to determine it is android app or not, False by default
        :type adb: bool
        :param serial_number: (optional) serial number of adb device
        :type serial_number: str
        :param host_configuration: (optional) host configuration for executing iperf command,
        None by default for localhost.
                mandatory parameters: host, username, password
                optional parameters: port, proxy_host, proxy_port, proxy_username, proxy_password
        :type host_configuration: dict
        :param log_path: iperf traffic statistic log path
        :type log_path: str
        :param iperf_alias:  (optional) alias for the new iperf instance, default is None
        :type iperf_alias: str
        :return: None
        """
        log_path = self._create_log_path(log_path)
        iperf_server = self._iperf_facade.create_iperf_server(cmd_options=cmd_options,
                                                              iperf_path=iperf_path,
                                                              adb=adb,
                                                              serial_number=serial_number,
                                                              host_configuration=host_configuration,
                                                              log_path=log_path)
        self.store.add(iperf_server, iperf_alias)

    def create_iperf_client(self,
                            cmd_options,
                            iperf_path=None,
                            adb=False,
                            serial_number=None,
                            host_configuration=None,
                            log_path=None,
                            iperf_alias=None):
        """
        Create iperf client instance.

        :param cmd_options: iperf software options string or dictionary
        dict:
                mandatory iperf software options: client
                optional iperf software options: udp, port, bandwidth, len, interval, bind, time, format, ipv6_domain,
                window, print_mss, mss, nodelay, tos, parallel, dualtest, ttl
                supported iperf software options can be found from the following NAA iperf software help doc.
                https://artifactory-espoo1.ext.net.nokia.com/artifactory/mn-android-apk/iperf/
                e.g.
                Create Dictionary
            ...  client=xxx.xxx.xxx.xxx
            ...  udp=True
            ...  interval=1
            ...  port=54000
            ...  bandwidth=5000k
            ...  time=120
            ...  len=1000
            ...  bind=xxx.xxx.xxx.xxx
        string:
                e.g. -u -c xxx.xxx.xxx.xxx -i 1 -p 54000 -b 5000k -t 120 -l 1000 -B xxx.xxx.xxx.xxx
        :type cmd_options: Union(str, dict)
        :param iperf_path: (optional) iperf path on the host, 'iperf' from $PATH by default
        :type iperf_path: str
        :param adb: (optional) flag to determine it is android app or not, False by default
        :type adb: bool
        :param serial_number: (optional) serial number of adb device
        :type serial_number: str
        :param host_configuration: (optional) host configuration for executing iperf command,
        None by default for localhost
                mandatory parameters: host, username, password
                optional parameters: port, proxy_host, proxy_port, proxy_username, proxy_password
        :type host_configuration: dict
        :param log_path: iperf traffic statistic log path
        :type log_path: str
        :param iperf_alias:  (optional) alias for the new iperf instance, default is None
        :type iperf_alias: str
        :return: None
        """
        log_path = self._create_log_path(log_path)
        iperf_client = self._iperf_facade.create_iperf_client(cmd_options=cmd_options,
                                                              iperf_path=iperf_path,
                                                              adb=adb,
                                                              serial_number=serial_number,
                                                              host_configuration=host_configuration,
                                                              log_path=log_path)
        self.store.add(iperf_client, iperf_alias)

    def create_iperf3_server(self,
                             cmd_options=None,
                             iperf_path=None,
                             adb=False,
                             serial_number=None,
                             host_configuration=None,
                             log_path=None,
                             iperf_alias=None):
        """
        Create iperf server instance.

        :param cmd_options: (optional) iperf software options string or dictionary except for -s/server
        which is built-in from this Keyword
        if the ue pc has multiple network interfaces, please use -B/bind to specify one
        dict:
                interval, bind, format, port
                supported iperf software options can be found from the following NAA iperf software help doc.
                https://artifactory-espoo1.ext.net.nokia.com/artifactory/mn-android-apk/iperf/
                e.g.
                Create Dictionary
            ...  interval=1
            ...  port=54000
            ...  bandwidth=5000k
            ...  bind=xxx.xxx.xxx.xxx

        string: e.g. -i 1 -p 54000 -b 5000k -B xxx.xxx.xxx.xxx
        :type cmd_options: Union(str, dict)
        :param iperf_path: (optional) iperf path on the host, 'iperf' from $PATH by default
        :type iperf_path: str
        :param adb: (optional) flag to determine it is android app or not, False by default
        :type adb: bool
        :param serial_number: (optional) serial number of adb device
        :type serial_number: str
        :param host_configuration: (optional) host configuration for executing iperf command,
        None by default for localhost
                mandatory parameters: host, username, password
                optional parameters: port, proxy_host, proxy_port, proxy_username, proxy_password
        :type host_configuration: dict
        :param log_path: iperf traffic statistic log path
        :type log_path: str
        :param iperf_alias:  (optional) alias for the new iperf instance, default is None
        :type iperf_alias: str
        :return: None
        """
        log_path = self._create_log_path(log_path)
        iperf_server = self._iperf_facade.create_iperf3_server(cmd_options=cmd_options,
                                                               iperf_path=iperf_path,
                                                               adb=adb,
                                                               serial_number=serial_number,
                                                               host_configuration=host_configuration,
                                                               log_path=log_path)
        self.store.add(iperf_server, iperf_alias)

    def create_iperf3_client(self,
                             cmd_options,
                             iperf_path=None,
                             adb=False,
                             serial_number=None,
                             host_configuration=None,
                             log_path=None,
                             iperf_alias=None):
        """
        Create iperf client instance.

        :param cmd_options: iperf software options string or dictionary
        dict:
                mandatory iperf software options: client
                optional iperf software options: udp, port, bitrate, length, interval, bind, time, format, window,
                set_mss, no_delay, tos, parallel, reverse
                supported iperf software options can be found from the following NAA iperf software help doc.
                https://artifactory-espoo1.ext.net.nokia.com/artifactory/mn-android-apk/iperf/
                e.g.
                Create Dictionary
            ...  udp=True
            ...  interval=1
            ...  port=54000
            ...  bandwidth=5000k
            ...  bind=xxx.xxx.xxx.xxx
        string: e.g. -u -p 540000 -i 1 -b 5000k -B xxx.xxx.xxx.xxx
        :type cmd_options: Union(str, dict)
        :param iperf_path: (optional) iperf path on the host, 'iperf' from $PATH by default
        :type iperf_path: str
        :param adb: (optional) flag to determine it is android app or not, False by default
        :type adb: bool
        :param serial_number: (optional) serial number of adb device
        :type serial_number: str
        :param host_configuration: (optional) host configuration for executing iperf command,
        None by default for localhost
                mandatory parameters: host, username, password
                optional parameters: port, proxy_host, proxy_port, proxy_username, proxy_password
        :type host_configuration: dict
        :param log_path: iperf traffic statistic log path
        :type log_path: str
        :param iperf_alias:  (optional) alias for the new iperf instance, default is None
        :type iperf_alias: str
        :return: None
        """
        log_path = self._create_log_path(log_path)
        iperf_client = self._iperf_facade.create_iperf3_client(cmd_options=cmd_options,
                                                               iperf_path=iperf_path,
                                                               adb=adb,
                                                               serial_number=serial_number,
                                                               host_configuration=host_configuration,
                                                               log_path=log_path)
        self.store.add(iperf_client, iperf_alias)

    @lookup_handler.implicit_lookup
    def _look_up(self, iperf):
        return iperf

    def _convert_alias_to_instance(self, iperfs):
        iperf_instances = []
        for iperf in iperfs:
            iperf_instances.append(self._look_up(iperf))
        return iperf_instances

    def setup(self, iperfs):
        """
        Setup the iperf instance in-sequence.

        :param iperfs: alias list for looking up the iperf instance
        :type iperfs: list
        :return: None

.. code-block:: Robot

        Example of Test cases:
        *********************

        *** Settings ***
        Library    taf.trafficgenerator.iperf   WITH NAME   iperf

        *** Variables ***
        ${iperf_log_path}  /xxx/xxx/xxx
        ${iperf_server_1}  iperf_server_1
        ${iperf_client_1}  iperf_client_1

        *** Test Cases ***
        Iperf Traffic TC
            ${iperf_server_host_configuration}=  Create Dictionary
            ...  host=xxx.xxx.xxx.xxx
            ...  username=xxxx
            ...  password=xxxx
            ${iperf_server_cmd_options_configuration}=  Create Dictionary
            ...  udp=True
            ...  interval=1
            ...  port=54000
            ...  bandwidth=5000k
            ...  time=120
            ...  len=1000
            ...  bind=xxx.xxx.xxx.xxx
            ${iperf_client_host_configuration}=  Create Dictionary
            ...  host=xxx.xxx.xxx.xxx
            ...  username=xxxx
            ...  password=xxxx
            ${iperf_client_cmd_options_configuration}=  Create Dictionary
            ...  client=xxx.xxx.xxx.xxx
            ...  udp=True
            ...  interval=1
            ...  port=54000
            ...  bandwidth=5000k
            ...  time=120
            ...  len=1000
            ...  bind=xxx.xxx.xxx.xxx

            iperf.create_iperf_server
            ...  cmd_options=${iperf_server_cmd_options_configuration}
            ...  iperf_path=/xxx/iperf'
            ...  host_configuration=${iperf_server_host_configuration}
            ...  log_path=${iperf_log_path}
            ...  iperf_alias=${iperf_server_1}
            iperf.create_iperf_client
            ...  cmd_options=${iperf_client_cmd_options_configuration}
            ...  iperf_path=/xxx/iperf'
            ...  host_configuration=${iperf_client_host_configuration}
            ...  log_path=${iperf_log_path}
            ...  iperf_alias=${iperf_client_1}
            ${iperf_list}=  Create List    ${iperf_server_1}    ${iperf_client_1}
            iperf.setup    iperfs=${iperf_list}
            iperf.start    iperfs=${iperf_list}
            Sleep    30
            iperf.stop    iperfs=${iperf_list}
            iperf.teardown
        """
        iperf_instances = self._convert_alias_to_instance(iperfs)
        self._iperf_facade.setup_iperfs(iperf_instances)

    def start(self, iperfs):
        """
        Start traffic in-sequence with iperf command.

        :param iperfs: alias list for looking up the iperf instance
        :type iperfs: list
        :return: None
        """
        iperf_instances = self._convert_alias_to_instance(iperfs)
        self._iperf_facade.start(iperf_instances)

    def stop(self, iperfs, timeout=None, prior=None, force=False):
        """
        Stop traffic in-sequence with iperf command.

        :param iperfs: alias list for looking up the iperf instance
        :type iperfs: list
        :param timeout: timeout for per kill of a single iperf, 30s by default,
        at most there will be soft kill and hard kill,
        so the timeout will be from 30 ~ 60 seconds in real
        :type timeout: int
        :param prior: which type of the iperf instance will be stopped first,
        options are "server", "client", "na", client by default, when it is "na", will follow the order in iperf list
        :type prior: str
        :param force: force to kill iperf process, False by default
        :type force: bool
        :return: None
        """
        timeout = int(timeout) if timeout else None
        iperf_instances = self._convert_alias_to_instance(iperfs)
        prior_map = {"server": StopPrior.Server, "client": StopPrior.Client, "na": StopPrior.NA}
        prior_value = StopPrior.Client
        if prior and prior.lower() in prior_map:
            prior_value = prior_map[prior.lower()]
        self._iperf_facade.stop(iperf_instances, timeout, prior_value, force)

    def teardown(self):
        """Teardown the iperf instance in-sequence."""
        self._iperf_facade.teardown_iperfs()
